// Устойчивый парсер: нормальный JSON, двойное кодирование, "голый" массив, и \" → " fallback
function tryParsePlan(t) {
  if (typeof t !== 'string') return null;
  const s = t.trim();
  if (!s) return null;
  try {
    const p = JSON.parse(s);
    if (Array.isArray(p)) return { summary: '', tasks: p };
    if (p && typeof p === 'object' && Array.isArray(p.tasks)) return p;
    if (typeof p === 'string') {
      const inner = JSON.parse(p.trim());
      if (Array.isArray(inner)) return { summary: '', tasks: inner };
      if (inner && typeof inner === 'object' && Array.isArray(inner.tasks)) return inner;
    }
  } catch (_) {}
  return null;
}

function parsePlan(text) {
  if (text == null) return { ok: false, reason: 'plan_json is null/undefined' };
  const raw = String(text).trim();
  if (!raw) return { ok: false, reason: 'plan_json is empty' };

  let plan = tryParsePlan(raw);
  if (plan) return { ok: true, plan, how: 'direct' };

  // Ключевой случай: в БД лежит {"...":"..."} — снимаем backslash перед кавычками
  const unescaped = raw.replace(/\\"/g, '"');
  plan = tryParsePlan(unescaped);
  if (plan) return { ok: true, plan, how: 'unescaped' };

  try {
    const decoded = JSON.parse('"' + raw.replace(/\r?\n/g, '\\n') + '"');
    plan = tryParsePlan(decoded);
    if (plan) return { ok: true, plan, how: 'json-string' };
  } catch (_) {}

  return { ok: false, reason: 'plan_json не удалось распарсить ни одним способом', raw };
}

const parsed = parsePlan(row.plan_json);

