  const stateKey = String(row.state_key ?? '');
  const preview = String(parsed.raw ?? '').slice(0, 300);
  throw new Error(`Saved task state for state_key="${stateKey}" has malformed plan_json.\nReason: ${parsed.reason}\nRaw value (first 300 chars): ${JSON.stringify(preview)}\nFix: удали строку со state_key="${stateKey}" в Autonomous Agent Task State и перезапусти workflow.`);
}

const plan = parsed.plan;
const tasks = plan.tasks;

if (!Array.isArray(tasks) || tasks.length === 0) {
  const stateKey = String(row.state_key ?? '');
  throw new Error(`Saved task state for state_key="${stateKey}" has an empty tasks array.`);
